import{_ as a,o as n,c as i,a3 as l}from"./chunks/framework.MGD2uYU7.js";const f=JSON.parse('{"title":"SC-02 — Danh sách tin","description":"","frontmatter":{"title":"SC-02 — Danh sách tin"},"headers":[],"relativePath":"wireframes/public/sc-02-danh-sach-tin.md","filePath":"wireframes/public/sc-02-danh-sach-tin.md","lastUpdated":1791606799000}'),t={name:"wireframes/public/sc-02-danh-sach-tin.md"};function e(p,s,c,d,r,o){return n(),i("div",null,[...s[0]||(s[0]=[l('<h1 id="sc-02-—-danh-sach-tin-noxh" tabindex="-1">SC-02 — Danh sách tin NOXH <a class="header-anchor" href="#sc-02-—-danh-sach-tin-noxh" aria-label="Permalink to &quot;SC-02 — Danh sách tin NOXH&quot;">​</a></h1><p><span class="wf-badge info">Route: /nha-o-xa-hoi</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-02 · docs/03 UC-03 · docs/02 FR-HS-06 · docs/08 BR-PKG-06</span></p><p><strong>Ai xem màn này</strong>: Guest + Thành viên đang tìm mua — vào từ search trang chủ (SC-01), link SEO, hoặc link chia sẻ (URL chứa sẵn filter). <strong>Mục đích / cảm xúc thiết kế</strong>: công cụ tìm kiếm nghiêm túc — filter rõ, kết quả đếm được, không quảng cáo chen ngang. URL là trạng thái: copy link gửi nhau phải ra đúng kết quả. <strong>Ví dụ số dùng trong bản vẽ</strong>: 137 tin · 7 trang · căn <code>CT2-A18.05</code> NOXH <code>HP-380</code> · <code>72 m²</code> · <code>1.250.000.000 ₫</code> · filter giá 1–1,5 tỷ, diện tích từ 60 m².</p><h2 id="_1-desktop-—-filter-rail-trai-grid-card-phai-pagination" tabindex="-1">1. Desktop — filter rail trái + grid card phải + pagination <a class="header-anchor" href="#_1-desktop-—-filter-rail-trai-grid-card-phai-pagination" aria-label="Permalink to &quot;1. Desktop — filter rail trái + grid card phải + pagination&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/nha-o-xa-hoi?projectId=prj_01J…&amp;priceMin=1000000000&amp;priceMax=1500000000&amp;areaMin=60&amp;sort=featured&amp;page=1 <span class="wf-callout">1</span></span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span class="active">Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-btn sm">Đăng nhập</span><span class="wf-btn sm primary">Đăng bán</span></span></div><div class="wf-container"><div class="wf-breadcrumb">Trang chủ › <b>Mua nhà ở xã hội</b></div><div class="wf-row" style="align-items:stretch;"><div class="wf-sidebar"><div class="wf-col" style="gap:12px;"><div class="wf-row between middle"><span class="wf-title">Bộ lọc <span class="wf-callout">2</span></span><span class="wf-small wf-accent">Xóa tất cả</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Từ khóa</span><div class="wf-search" style="flex:none;">🔍 CT2-A18</div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Dự án</span><div class="wf-input filled">NOXH HP-380 <span class="caret">▾</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Giá (₫)</span><div class="wf-row"><div class="wf-input filled" style="flex:1;">1.000.000.000</div><div class="wf-input filled" style="flex:1;">1.500.000.000</div></div><span class="wf-small">Min lớn hơn max → ô đỏ + &quot;Giá tối thiểu phải nhỏ hơn giá tối đa&quot;</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Diện tích (m²)</span><div class="wf-row"><div class="wf-input filled" style="flex:1;">60</div><div class="wf-input" style="flex:1;">Tối đa</div></div></div><div class="wf-col" style="gap:6px;"><span class="wf-small">Phòng ngủ</span><span class="wf-checkbox">1 PN</span><span class="wf-checkbox checked">2 PN</span><span class="wf-checkbox">3 PN+</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Sắp xếp <span class="wf-callout">3</span></span><div class="wf-input filled">Nổi bật (VIP trước) <span class="caret">▾</span></div><span class="wf-small">Tùy chọn: newest (mặc định) · price_asc · price_desc · featured</span></div></div></div><div class="wf-grow wf-col"><div class="wf-row between middle"><span class="wf-text"><b>137</b> tin phù hợp <span class="wf-callout">4</span></span><span class="wf-row middle" style="gap:6px;"><span class="wf-badge muted">Dự án: NOXH HP-380 ✕</span><span class="wf-badge muted">Giá 1–1,5 tỷ ✕</span><span class="wf-badge muted">≥60 m² ✕</span></span></div><div class="wf-grid cols-3"><div class="wf-card" style="border-color:var(--wf-accent);"><div class="wf-img" style="min-height:130px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span class="wf-badge wf-vip">★ VIP</span><span class="wf-badge ok">Đang bán</span></span><span class="wf-title">Căn CT2-A18.05</span><span class="wf-text">NOXH HP-380 · Vĩnh Niệm, Lê Chân, Hải Phòng</span><span class="wf-text">72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng</span><div class="wf-row between middle"><span class="wf-money lg">1.250.000.000 ₫</span><span class="wf-small">17,4 tr/m²</span></div><span class="wf-small">Đăng 02/10/2026 08:00 (GMT+7)</span></div></div><div class="wf-card"><div class="wf-img" style="min-height:130px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span></span><span class="wf-badge ok">Đang bán</span></span><span class="wf-title">Căn CT1-B09.03</span><span class="wf-text">NOXH HP-380 · Vĩnh Niệm, Lê Chân, Hải Phòng</span><span class="wf-text">68 m² · 2 PN · 1 WC · tầng 9 · Sổ hồng</span><div class="wf-row between middle"><span class="wf-money lg">1.180.000.000 ₫</span><span class="wf-small">17,4 tr/m²</span></div><span class="wf-small">Đăng 01/10/2026 15:20 (GMT+7)</span></div></div><div class="wf-card"><div class="wf-img" style="min-height:130px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span></span><span class="wf-badge muted">Sắp đấu giá</span></span><span class="wf-title">Căn CT2-A11.02</span><span class="wf-text">NOXH HP-380 · Vĩnh Niệm, Lê Chân, Hải Phòng</span><span class="wf-text">70 m² · 2 PN · 1 WC · tầng 11 · Sổ hồng</span><div class="wf-row between middle"><span class="wf-money lg">1.300.000.000 ₫</span><span class="wf-small">18,6 tr/m²</span></div><span class="wf-small">Phiên mở 12/10/2026 14:00 <span class="wf-callout">5</span></span></div></div></div><span class="wf-small">… lưới 3 cột × tối đa 20 tin/trang (limit default 20, max 50 — docs/06 §1)</span><div class="wf-pagination"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">3</span><span class="pg">…</span><span class="pg">7</span><span class="pg">›</span></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-02 · docs/02 FR-HS-06 · docs/06)</div><ol><li><span class="num">1</span><span><b>URL-sync toàn bộ query</b>: mọi thay đổi filter/sort/page ghi lên query string (replaceState, debounce 300ms) — link copy được, share được, back/forward trình duyệt hoạt động. Param khớp API: `q, projectId, priceMin, priceMax, areaMin, areaMax, sort, page, limit`. <span class="ref">FR-HS-06</span> <span class="ref">docs/06 §4.1</span></span></li><li><span class="num">2</span><span><b>Filter validate phía FE trước khi gọi</b>: giá min lớn hơn giá max → field-error đỏ &quot;Giá tối thiểu phải nhỏ hơn giá tối đa&quot;, không gửi request (BE ignore cặp vô hiệu — UC-03 EF-2). Ô &quot;Dự án&quot; là select search-as-you-type từ `GET /projects?q=`. <span class="ref">UC-03 EF-2</span> <span class="ref">docs/06 §3 endpoint 11</span></span></li><li><span class="num">3</span><span><b>Sort mặc định = newest</b> (`listedAt desc`). `featured` = quy tắc tĩnh: <b>VIP trước rồi newest — không AI</b>; card VIP có badge ★ + viền accent. Đến từ SC-01 qua link &quot;featured&quot; thì preselect. <span class="ref">BR-PKG-06</span> <span class="ref">FR-HS-06</span></span></li><li><span class="num">4</span><span>Đếm kết quả lấy từ `metadata.total`. Chip filter đang áp dụng (có ✕) hiện trên đầu grid — bấm ✕ gỡ 1 filter và cập nhật URL. Badge trạng thái tin: Đang bán = LISTED (xanh), Sắp đấu giá = RESERVED (xám) — màu theo enum docs/07 §3. <span class="ref">docs/06 §1</span> <span class="ref">docs/07 §3</span></span></li><li><span class="num">5</span><span>Tin RESERVED có phiên: card hiện thêm dòng giờ mở phiên; click card vẫn vào SC-03 (từ đó link sang SC-06). Chỉ tin LISTED/RESERVED/SOLD xuất hiện public — DRAFT/IN_REVIEW/REJECTED không bao giờ lộ. <span class="ref">FR-HS-07</span></span></li><li><span class="num">6</span><span>Pagination offset `page/limit`; đổi trang scroll lên đầu grid; `page` vượt totalPages → BE trả rỗng, FE redirect về page cuối hợp lệ. Public GET có cache `s-maxage=30` — số liệu có thể trễ tối đa 30s, chấp nhận được. <span class="ref">docs/06 §6.4</span></span></li></ol></div><h2 id="_2-mobile-360px-—-filter-thu-vao-drawer" tabindex="-1">2. Mobile 360px — filter thu vào drawer <a class="header-anchor" href="#_2-mobile-360px-—-filter-thu-vao-drawer" aria-label="Permalink to &quot;2. Mobile 360px — filter thu vào drawer&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — DANH SÁCH (filter ẩn)</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔</span></div><div class="wf-container" style="padding:12px;"><div class="wf-search">🔍 CT2-A18</div><div class="wf-row between middle" style="margin-top:10px;"><span class="wf-btn sm">⚙ Bộ lọc (3) <span class="wf-callout">7</span></span><span class="wf-btn sm">Sắp xếp: Nổi bật ▾</span></div><div class="wf-row wrap" style="margin-top:8px;gap:6px;"><span class="wf-badge muted">HP-380 ✕</span><span class="wf-badge muted">1–1,5 tỷ ✕</span><span class="wf-badge muted">≥60 m² ✕</span></div><span class="wf-text" style="display:block;margin-top:8px;"><b>137</b> tin phù hợp</span><div class="wf-card" style="margin-top:8px;"><div class="wf-img" style="min-height:110px;border-radius:0;border:none;border-bottom:1px solid var(--wf-line);"><span>ẢNH BÌA</span></div><div class="pad wf-col" style="gap:4px;"><span class="wf-row between"><span class="wf-badge wf-vip">★ VIP</span><span class="wf-badge ok">Đang bán</span></span><span class="wf-title">Căn CT2-A18.05 — NOXH HP-380</span><span class="wf-text">72 m² · 2 PN · 1 WC · tầng 18 · Sổ hồng</span><span class="wf-money lg">1.250.000.000 ₫</span></div></div><div class="wf-pagination"><span class="pg">‹</span><span class="pg active">1</span><span class="pg">2</span><span class="pg">…</span><span class="pg">7</span><span class="pg">›</span></div></div></div></div><div><span class="wf-state-label">MOBILE — DRAWER &quot;BỘ LỌC&quot; ĐANG MỞ</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-drawer" style="width:100%;border-radius:0;min-height:420px;"><div class="wf-row between middle"><span class="wf-title">Bộ lọc</span><span class="wf-btn sm ghost">Đóng ✕</span></div><div class="wf-col" style="gap:12px;margin-top:12px;"><div class="wf-col" style="gap:4px;"><span class="wf-small">Dự án</span><div class="wf-input filled">NOXH HP-380 <span class="caret">▾</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Giá (₫)</span><div class="wf-row"><div class="wf-input filled" style="flex:1;">1.000.000.000</div><div class="wf-input filled" style="flex:1;">1.500.000.000</div></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small">Diện tích (m²)</span><div class="wf-row"><div class="wf-input filled" style="flex:1;">60</div><div class="wf-input" style="flex:1;">Tối đa</div></div></div><div class="wf-col" style="gap:6px;"><span class="wf-small">Phòng ngủ</span><span class="wf-checkbox checked">2 PN</span><span class="wf-checkbox">3 PN+</span></div><div class="wf-row" style="margin-top:4px;"><span class="wf-btn ghost" style="flex:1;">Xóa lọc</span><span class="wf-btn primary" style="flex:2;">Xem 137 tin <span class="wf-callout">8</span></span></div></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">7</span><span>Rail trái biến thành nút &quot;Bộ lọc (N)&quot; — N = số filter đang áp, cạnh nút sort. Drawer mở từ đáy (bottom sheet) trên mobile thật; wireframe vẽ dạng panel full-width. Chip filter hoạt động y hệt desktop (bấm ✕ gỡ ngay, không cần mở drawer).</span></li><li><span class="num">8</span><span>Drawer mobile <b>chỉ áp dụng khi bấm &quot;Xem N tin&quot;</b> (nút hiện count preview) — khác desktop (áp dụng tức thì). Lý do: tránh refetch mỗi lần chạm trên mạng di động. URL vẫn sync khi đóng drawer.</span></li></ol></div><h2 id="_3-loading-—-skeleton-grid" tabindex="-1">3. Loading — skeleton grid <a class="header-anchor" href="#_3-loading-—-skeleton-grid" aria-label="Permalink to &quot;3. Loading — skeleton grid&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:760px;"><span class="wf-state-label">TRẠNG THÁI: LOADING (đổi filter / sang trang)</span><div class="wf-grid cols-3"><div class="wf-skeleton"><div class="wf-img" style="min-height:110px;"><span></span></div><div class="wf-lines"><span class="w-40"></span><span class="w-90"></span><span class="w-60"></span><span class="w-75"></span></div></div><div class="wf-skeleton"><div class="wf-img" style="min-height:110px;"><span></span></div><div class="wf-lines"><span class="w-50"></span><span class="w-75"></span><span class="w-40"></span><span class="w-90"></span></div></div><div class="wf-skeleton"><div class="wf-img" style="min-height:110px;"><span></span></div><div class="wf-lines"><span class="w-60"></span><span class="w-90"></span><span class="w-50"></span><span class="w-75"></span></div></div></div><span class="wf-small">Filter rail giữ nguyên giá trị đang chọn (không skeleton); grid mờ đi + skeleton khi refetch. Đổi trang: skeleton đủ 20 ô tránh nhảy layout.</span></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">9</span><span>Skeleton card dùng chung component với SC-01 (mục 3). Request có cache 30s nên lần vào lại thường instant — skeleton chỉ hiện khi miss cache hoặc đổi query. <span class="ref">docs/05 §1.4</span> <span class="ref">docs/06 §6.4</span></span></li></ol></div><h2 id="_4-empty-—-khong-tim-thay-clear-filters" tabindex="-1">4. Empty — &quot;Không tìm thấy&quot; + clear filters <a class="header-anchor" href="#_4-empty-—-khong-tim-thay-clear-filters" aria-label="Permalink to &quot;4. Empty — &quot;Không tìm thấy&quot; + clear filters&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:560px;"><span class="wf-state-label">TRẠNG THÁI: EMPTY (filter quá hẹp — 0 kết quả)</span><div class="wf-empty"><span class="icon">🔍</span><span class="wf-title">Không tìm thấy tin phù hợp</span><br><span class="wf-text">Thử bỏ bớt bộ lọc hoặc mở rộng khoảng giá / diện tích. Tin NOXH mới được đăng liên tục — quay lại sau.</span><div class="wf-row" style="justify-content:center;margin-top:10px;"><span class="wf-btn primary">Xóa toàn bộ bộ lọc <span class="wf-callout">10</span></span><span class="wf-btn ghost">Xem dự án NOXH</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">10</span><span>&quot;Xóa toàn bộ bộ lọc&quot; → reset về `/nha-o-xa-hoi` (mất hết query, giữ nguyên sort=newest mặc định) và refetch. Empty khác Error: không traceId, không nút &quot;Thử lại&quot;. <span class="ref">docs/05 §3</span></span></li></ol></div><h2 id="_5-error-retry-traceid" tabindex="-1">5. Error + retry + traceId <a class="header-anchor" href="#_5-error-retry-traceid" aria-label="Permalink to &quot;5. Error + retry + traceId&quot;">​</a></h2><div class="wf"><div class="wf-col" style="max-width:560px;"><span class="wf-state-label">TRẠNG THÁI: ERROR (GET /housing thất bại)</span><div class="wf-error-box"><span class="wf-title" style="color:var(--wf-danger);">Không tải được danh sách tin</span><br><span class="wf-small">Đã xảy ra lỗi khi tải dữ liệu. Vui lòng thử lại.</span><br><span class="wf-trace">traceId: 4c81fe02…</span><div class="wf-row" style="justify-content:center;margin-top:10px;"><span class="wf-btn primary">Thử lại <span class="wf-callout">11</span></span></div></div><div class="wf-note">Riêng 429 (vượt 100 request/phút/IP của `GET /housing`): hiện &quot;Bạn đang thao tác quá nhanh — thử lại sau ít phút&quot;, nút Thử lại disabled kèm countdown, không tính là lỗi hệ thống.</div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">11</span><span>&quot;Thử lại&quot; refetch đúng query hiện tại trên URL; traceId rút gọn 8 ký tự để đọc qua điện thoại cho CSKH. FE phân nhánh theo field `error` trong envelope, <b>không parse message</b>. <span class="ref">docs/06 §1</span> <span class="ref">docs/06 §3 endpoint 13</span></span></li></ol></div><h2 id="_6-checklist-designer-khi-dung-figma-cho-sc-02" tabindex="-1">6. Checklist designer khi dựng Figma cho SC-02 <a class="header-anchor" href="#_6-checklist-designer-khi-dung-figma-cho-sc-02" aria-label="Permalink to &quot;6. Checklist designer khi dựng Figma cho SC-02&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (rail 220px + grid 3 cột) / tablet 768 (rail thu thành drawer, grid 2 cột) / mobile 360 (1 cột + bottom sheet filter)</li><li>[ ] Đủ 4 trạng thái: Loading skeleton · Empty + clear filters · Error + traceId + Thử lại · Data</li><li>[ ] Filter rail đủ control: search text, select dự án (search-as-you-type), 2 ô giá min/max, 2 ô diện tích, checkbox phòng ngủ, select sort (4 giá trị)</li><li>[ ] Card tin đủ biến thể: ★ VIP + viền accent / badge Đang bán (LISTED) / badge Sắp đấu giá (RESERVED + giờ mở phiên)</li><li>[ ] Chip filter đang áp dụng ( removable ✕ ) vẽ cả trên desktop lẫn mobile; count preview trên nút &quot;Xem N tin&quot; của drawer</li><li>[ ] Validate FE: giá min lớn hơn giá max → field error đỏ, không gọi API</li><li>[ ] Copy đúng docs/06 §5; tiền <code>1.250.000.000 ₫</code>; ngày <code>dd/MM/yyyy HH:mm</code> + GMT+7</li><li>[ ] Không emoji icon trong UI production (🔍/⚙ trong wireframe là placeholder vị trí)</li><li>[ ] Accessibility: label cho mọi input filter; drawer trap focus + đóng bằng Esc; pagination có aria-current; kết quả có aria-live khi refetch</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd tiêu chí featured, limit trang) cần PM duyệt trên docs/08 trước.</p></div>',21)])])}const g=a(t,[["render",e]]);export{f as __pageData,g as default};
